using System.Data;
using System.IO;
using System.Security.Cryptography;
using System.Text;
using System.Text.Json;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Documents;
using System.Windows.Input;
using System.Windows.Media;
using Microsoft.Win32;
using DDHI.Pharmacy.Contracts;
namespace DDHI.Pharmacy.Desktop;

public sealed class DrugReferenceView:UserControl
{
    readonly ListBox sections=new(){Width=205};readonly TextBox search=new(){MinWidth=230};readonly CheckBox stockOnly=new(){Content="In hospital stock",Margin=new Thickness(8)};
    readonly WrapPanel toolbar=new();readonly DataGrid grid=new(){AutoGenerateColumns=true,IsReadOnly=true,CanUserAddRows=false,Height=150,RowHeight=36,ColumnHeaderHeight=36,Background=Brushes.White,GridLinesVisibility=DataGridGridLinesVisibility.Horizontal,HeadersVisibility=DataGridHeadersVisibility.Column};
    readonly StackPanel details=new();readonly TextBlock status=new(){TextWrapping=TextWrapping.Wrap,Foreground=Brushes.DarkRed};readonly ListBox basket=new(){Height=95};
    readonly Dictionary<Guid,string> selectedMedicines=[];readonly Dictionary<string,List<KeyValuePair<string,string>>> empty=[];
    MainViewModel? vm;JsonElement? monograph;JsonElement? screenResponse;bool expanded;string current="Drug Search";CancellationTokenSource? debounce;
    public Action<string>? SessionEnded {get;set;}
    public (Guid Id,string Name)[] Basket=>selectedMedicines.Select(x=>(x.Key,x.Value)).ToArray();
    public async Task OpenMedicine(Guid id){monograph=await vm!.Get("clinical/monograph/"+id);ShowMonograph();}
    public DrugReferenceView()
    {
        sections.Background=(Brush)new BrushConverter().ConvertFromString("#103D31")!;sections.Foreground=Brushes.White;sections.BorderThickness=new Thickness(0);sections.ItemContainerStyle=(Style)Application.Current.FindResource("SidebarNavigationItem");ScrollViewer.SetHorizontalScrollBarVisibility(sections,ScrollBarVisibility.Disabled);
        search.ToolTip="Search generic, brand, ingredient, synonym, class, manufacturer, registration, indication or approved barcode";System.Windows.Automation.AutomationProperties.SetName(search,"Drug reference search");
        var layout=new DockPanel();Content=layout;DockPanel.SetDock(sections,Dock.Left);layout.Children.Add(sections);var right=new DockPanel{Margin=new Thickness(14,0,0,0)};layout.Children.Add(right);
        var top=new StackPanel();DockPanel.SetDock(top,Dock.Top);right.Children.Add(top);top.Children.Add(new Border{Background=(Brush)new BrushConverter().ConvertFromString("#FFF5D6")!,Padding=new Thickness(10),Child=status});
        var searchbar=new WrapPanel();searchbar.Children.Add(search);searchbar.Children.Add(stockOnly);var find=new Button{Content="Search / verify selection"};searchbar.Children.Add(find);top.Children.Add(searchbar);top.Children.Add(toolbar);top.Children.Add(grid);
        var bottom=new StackPanel();DockPanel.SetDock(bottom,Dock.Bottom);right.Children.Add(bottom);bottom.Children.Add(new Expander{Header="Screening list - reviewed active medicines only",IsExpanded=false,Content=basket,Margin=new Thickness(0,6,0,2)});var actions=new WrapPanel();bottom.Children.Add(actions);
        void Action(string title,Func<Task> task){var button=new Button{Content=title};actions.Children.Add(button);button.Click+=async(_,_)=>await Guard(task);}
        Action("Add selected",AddSelected);Action("Remove",()=>{if(basket.SelectedItem is KeyValuePair<Guid,string> item)selectedMedicines.Remove(item.Key);RefreshBasket();return Task.CompletedTask;});Action("Clear list",()=>{selectedMedicines.Clear();RefreshBasket();screenResponse=null;return Task.CompletedTask;});Action("Run safety check",Screen);
        right.Children.Add(new ScrollViewer{Content=details,VerticalScrollBarVisibility=ScrollBarVisibility.Auto});
        sections.SelectionChanged+=async(_,_)=>{if(sections.SelectedItem is string name){current=name;await Guard(LoadSection);}};
        find.Click+=async(_,_)=>await Guard(Search);search.KeyDown+=async(_,e)=>{if(e.Key==Key.Enter){e.Handled=true;await Guard(Search);}};
        search.TextChanged+=async(_,_)=>{debounce?.Cancel();var pending=debounce=new();try{await Task.Delay(450,pending.Token);if(IsVisible&&vm?.UserId.Length>0)await Guard(Search);}catch(OperationCanceledException){}};
        grid.MouseDoubleClick+=async(_,_)=>await Guard(OpenSelected);
        grid.AutoGeneratingColumn+=(_,e)=>{if(e.PropertyName.Equals("id",StringComparison.OrdinalIgnoreCase)){e.Cancel=true;return;}var label=System.Text.RegularExpressions.Regex.Replace(e.PropertyName,"([A-Z])"," $1").Trim();e.Column.Header=char.ToUpperInvariant(label[0])+label[1..];e.Column.MaxWidth=280;e.Column.MinWidth=75;if(e.Column is DataGridTextColumn column){var style=new Style(typeof(TextBlock));style.Setters.Add(new Setter(MarginProperty,new Thickness(7,0,7,0)));style.Setters.Add(new Setter(VerticalAlignmentProperty,VerticalAlignment.Center));style.Setters.Add(new Setter(ToolTipProperty,column.Binding));column.ElementStyle=style;}};
    }
    public async Task Configure(MainViewModel model)
    {
        vm=model;sections.ItemsSource=DrugReferenceSections.All.Where(s=>(s!="Database Administration"||ClientAccessPolicy.Has(model.Roles,"Clinical")||ClientAccessPolicy.Has(model.Roles,"Admin"))&&(s!="Drug Safety Alerts"||ClientAccessPolicy.Has(model.Roles,"Audit"))).ToArray();
        if(sections.SelectedIndex<0)sections.SelectedIndex=0;else await LoadSection();
        var health=await vm.Get("clinical/status");status.Text=health.GetProperty("databaseVersion").ToString()+" | "+health.GetProperty("coverage").ToString()+" | Unmapped inventory: "+health.GetProperty("unmappedInventory");
    }
    public void Reset(){recent.Clear();debounce?.Cancel();selectedMedicines.Clear();RefreshBasket();details.Children.Clear();grid.ItemsSource=null;screenResponse=null;monograph=null;search.Text="";vm=null;}
    async Task Guard(Func<Task> task){if(vm==null)return;try{await task();}catch(StaffSessionEndedException ex){Reset();SessionEnded?.Invoke(ex.Message);}catch(Exception ex){status.Text=ex is System.Net.Http.HttpRequestException or TaskCanceledException?"Server unavailable. Reference and safety decisions cannot be completed offline from the hospital server.":ex.Message;}}
    void Button(string title,Func<Task> task){var button=new Button{Content=title};toolbar.Children.Add(button);button.Click+=async(_,_)=>await Guard(task);}
    void RefreshBasket(){basket.ItemsSource=null;basket.ItemsSource=selectedMedicines.ToArray();basket.DisplayMemberPath="Value";}
    string Value(string key){if(grid.SelectedItem is DataRowView row)foreach(DataColumn c in row.DataView.Table!.Columns)if(c.ColumnName.Equals(key,StringComparison.OrdinalIgnoreCase))return row[c.ColumnName]?.ToString()??"";throw new InvalidOperationException("Select an appropriate record first.");}
    void Rows(JsonElement value){var table=new DataTable();var rows=value.ValueKind==JsonValueKind.Array?value.EnumerateArray().ToArray():[value];foreach(var row in rows)foreach(var p in row.EnumerateObject())if(!table.Columns.Contains(p.Name))table.Columns.Add(p.Name);foreach(var row in rows){var item=table.NewRow();foreach(var p in row.EnumerateObject())item[p.Name]=p.Value.ValueKind==JsonValueKind.String&&p.Value.GetString() is string str&&str.Contains('T')&&DateTimeOffset.TryParse(str,out var date)?date.ToOffset(TimeSpan.FromHours(8)).ToString("yyyy-MM-dd HH:mm:ss"):p.Value.ToString();table.Rows.Add(item);}grid.ItemsSource=table.DefaultView;}
    async Task LoadSection()
    {
        toolbar.Children.Clear();details.Children.Clear();monograph=null;screenResponse=null;grid.ItemsSource=null;
        Button("Open monograph",OpenSelected);Button("Concise / expanded",()=>{expanded=!expanded;ShowMonograph();return Task.CompletedTask;});Button("Scan / enter barcode",Barcode);
        Button("Reading window",()=>{FrameworkElement view;if(monograph!=null)view=ClinicalPresentation.Monograph(monograph.Value,true);else if(screenResponse is JsonElement response){var result=response.TryGetProperty("Result",out var upper)?upper:response.GetProperty("result");view=ClinicalPresentation.Safety(result.Deserialize<ClinicalScreenResult>(new JsonSerializerOptions{PropertyNameCaseInsensitive=true})!);}else throw new InvalidOperationException("Open a monograph or run a safety check first.");new Window{Title="DDHI clinical reading view",Owner=Window.GetWindow(this),Width=1000,Height=Math.Min(820,SystemParameters.WorkArea.Height),WindowStartupLocation=WindowStartupLocation.CenterOwner,Content=new ScrollViewer{Content=view,Padding=new Thickness(22),VerticalScrollBarVisibility=ScrollBarVisibility.Auto}}.ShowDialog();return Task.CompletedTask;});
        Button("Favorite",()=>Favorite(true));Button("Unfavorite",()=>Favorite(false));Button("Favorites",async()=>Rows(await vm!.Get("clinical/favorites")));Button("Recent searches",Recent);
        Button("Print / PDF",Print);Button("Export report",Export);
        Button("Reference guide",()=>{var path=Path.Combine(AppContext.BaseDirectory,"Documentation","DDHI-Drug-Reference-Guide.pdf");if(!File.Exists(path))throw new InvalidOperationException("Install the matching complete client package to open the reference guide.");System.Diagnostics.Process.Start(new System.Diagnostics.ProcessStartInfo(path){UseShellExecute=true});return Task.CompletedTask;});
        if(current=="Database Administration"){
            Button("Content versions",async()=>Rows(await vm!.Get("clinical/versions")));Button("Review history",async()=>Rows(await vm!.Get("clinical/reviews")));
            if(ClientAccessPolicy.Has(vm!.Roles,"Clinical")){Button("Import / preview package",Import);Button("Edit source package",EditPackage);Button("Content decision",Decide);Button("Map inventory medicine",Map);}
            if(ClientAccessPolicy.Has(vm!.Roles,"Chief"))Button("Hospital safety policy",async()=>{var old=await vm.Get("clinical/policy");var form=new FormWindow("Chief Pharmacist medication safety policy",[new("allow","Allow documented independent pharmacist review when database coverage is incomplete (hospital authorization required)","bool",old.GetProperty("allowDocumentedIncompleteReview").GetBoolean()?"true":"false"),new("moderate","Interrupt moderate alerts","bool",old.GetProperty("interruptModerate").GetBoolean()?"true":"false"),new("reference","Written hospital approval reference")],empty){Owner=Window.GetWindow(this)};if(form.ShowDialog()==true)await vm.Post("clinical/policy",new ClinicalSafetyPolicy((bool)form.Values["allow"]!,(bool)form.Values["moderate"]!,form.Values["reference"]!.ToString()!));});
            ClinicalPresentation.Heading(details,"Clinical content governance");ClinicalPresentation.Line(details,"Import JSON, CSV, CSV-bundle ZIP or .xlsx template. Preview and verify rights, submit for another pharmacist's review, then obtain Chief Pharmacist approval before publication. Editing creates a new version. Restoring an earlier publication preserves all screening/audit history. Hospital clinical validation is required.");return;
        }
        if(current=="Drug Safety Alerts"){Button("Screening history",async()=>Rows(await vm!.Get("clinical/screenings")));Button("Interventions",async()=>Rows(await vm!.Get("clinical/interventions")));ClinicalPresentation.Line(details,"Authorized audit users can review screening/intervention records. Open a screening by selecting its row and choosing Open screening.");Button("Open screening",async()=>{var response=await vm!.Get("clinical/screenings/"+Value("id"));screenResponse=response;ShowSafety(response.GetProperty("result"));AppendSafetyContext(response);});return;}
        if(current=="Clinical References and Updates"){Rows(await vm!.Get("clinical/status"));ClinicalPresentation.Heading(details,"Sources, versions and updates");ClinicalPresentation.Line(details,"The runtime uses only the hospital's published local database. No automatic internet retrieval or publication occurs. Source/license metadata is required in each import. RxNorm is terminology, not a comprehensive interaction database. WHO ATC, Philippine product registration and licensed IV data require their own source checks. Downloaded packages are staged and checked before any publication.");return;}
        if(current=="AI Drug Assistant"){ClinicalPresentation.Heading(details,"Approved-source lookup; external AI is disabled");ClinicalPresentation.Line(details,"Search approved monographs and source records using the search field. No generated answer or medication decision is produced, and no patient information leaves the hospital server. External AI credentials, subscriptions and internet access are not required.");}
        if(current=="IV Compatibility")ClinicalPresentation.Line(details,"IV evidence is separate from ordinary drug interactions. Exact concentration with units, diluent, temperature, container and contact conditions are required. Missing/unsupported evidence is UNKNOWN.",Brushes.DarkRed);
        if(current is "Dosage Reference" or "Renal Dosage Guide" or "Hepatic Dosage Guide")ClinicalPresentation.Line(details,"Medication-specific doses and renal/hepatic adjustments require published reviewed content. No dose or renal-function method is inferred. Validated patient dose calculators are not enabled in this foundation release.",Brushes.DarkRed);
        await Search();
    }
    async Task Search()
    {
        if(vm==null)return;var directory=current switch{"Generic Drug Directory"=>"drugs","Brand Directory"=>"products","Therapeutic Classification"=>"classes","DDHI Hospital Formulary"=>"formulary",_=>""};
        var result=await vm.Get("clinical/search?q="+Uri.EscapeDataString(search.Text)+"&stock="+(stockOnly.IsChecked==true?"true":"false")+"&directory="+directory);Rows(result.GetProperty("rows"));status.Text=$"{result.GetProperty("total")} results (up to 200 shown). "+(result.GetProperty("suggestions").GetBoolean()?"Spelling suggestions require exact-product verification. ":"")+"Missing clinical coverage stays UNKNOWN. "+result.GetProperty("stockMeaning");
    }
    readonly List<(Guid Id,string Label)> recent=[];
    Task Recent(){Rows(JsonSerializer.SerializeToElement(recent.Select(x=>new{x.Id,Name=x.Label})));return Task.CompletedTask;}
    async Task OpenSelected(){var id=Guid.Parse(Value("id"));monograph=await vm!.Get("clinical/monograph/"+id);recent.RemoveAll(x=>x.Id==id);recent.Insert(0,(id,"Reference "+id));if(recent.Count>20)recent.RemoveAt(20);ShowMonograph();}
    void ShowMonograph(){if(monograph==null)return;details.Children.Clear();var section=current switch{"Dosage Reference"=>"AdultDose","Renal Dosage Guide"=>"Renal","Hepatic Dosage Guide"=>"Hepatic","Pregnancy and Lactation"=>"Pregnancy","Antibiotic Reference"=>"Antibiotic","IV Compatibility"=>"IVCompatibility","DDHI Hospital Formulary"=>"Formulary",_=>""};details.Children.Add(ClinicalPresentation.Monograph(monograph.Value,expanded,section));if(current=="Pregnancy and Lactation")details.Children.Add(ClinicalPresentation.Monograph(monograph.Value,true,"Lactation"));}
    Task AddSelected(){var id=Guid.Parse(Value("id"));if(selectedMedicines.Count>=30&&!selectedMedicines.ContainsKey(id))throw new InvalidOperationException("Maximum 30 medicines per assessment.");string label;try{label=Value("generic")+" / "+Value("brand")+" / "+Value("strength");}catch{label=id.ToString();}selectedMedicines[id]=label;RefreshBasket();screenResponse=null;return Task.CompletedTask;}
    async Task Barcode(){var form=new FormWindow("Registered barcode lookup",[new("barcode","Scan or enter the full medicine barcode")],empty){Owner=Window.GetWindow(this)};if(form.ShowDialog()!=true)return;var response=await vm!.Post("clinical/barcode",new{barcode=form.Values["barcode"]});if(response.GetProperty("medicineId").ValueKind==JsonValueKind.Null){status.Text=response.GetProperty("message").ToString();return;}var id=response.GetProperty("medicineId").GetGuid();monograph=await vm.Get("clinical/monograph/"+id);ShowMonograph();var inventory=monograph.Value.GetProperty("inventory");selectedMedicines[id]=inventory.ValueKind==JsonValueKind.Object?inventory.GetProperty("genericName").ToString()+" / "+inventory.GetProperty("brandName"):monograph.Value.GetProperty("drug").GetProperty("name").ToString()+" (reference-only package)";RefreshBasket();}
    async Task Favorite(bool favorite)=>await vm!.Post("clinical/favorite",new{medicineId=Guid.Parse(Value("id")),favorite});
    async Task Screen(){if(Basket.Length==0)throw new InvalidOperationException("Add medicines to the screening list first.");var dialog=new ClinicalContextWindow(Basket,current=="IV Compatibility"?"IVCompatibility":""){Owner=Window.GetWindow(this)};if(dialog.ShowDialog()!=true||dialog.Assessment==null)return;screenResponse=await vm!.Post("clinical/screen",dialog.Assessment);ShowSafety(screenResponse.Value.GetProperty("Result"));AppendSafetyContext(screenResponse.Value);if(ClientAccessPolicy.Has(vm.Roles,"Clinical")){var review=new SafetyReviewWindow(screenResponse.Value.GetProperty("Id").GetGuid(),screenResponse.Value.GetProperty("Result").Deserialize<ClinicalScreenResult>()!){Owner=Window.GetWindow(this)};if(review.ShowDialog()==true&&review.Decision!=null){await vm.Post("clinical/interventions",review.Decision);status.Text="Pharmacist intervention recorded. A dispensing assessment must separately match the exact order, batch and quantity.";}}}
    void AppendSafetyContext(JsonElement response){ClinicalPresentation.Heading(details,"Screening provenance",18);ClinicalPresentation.Line(details,"Staff: "+vm!.StaffEmail+" | Roles: "+vm.RoleLabel+" | Workstation: "+vm.WorkstationId);foreach(var key in new[]{"Id","CreatedAt","ExpiresAt","id","createdAt","encounterReference"})if(response.TryGetProperty(key,out var value))ClinicalPresentation.Line(details,key+": "+value);foreach(var key in new[]{"Sources","sourceReferences"})if(response.TryGetProperty(key,out var sources))foreach(var source in sources.EnumerateArray())ClinicalPresentation.Line(details,string.Join(" | ",source.EnumerateObject().Select(p=>p.Name+": "+p.Value)));}
    void ShowSafety(JsonElement result){details.Children.Clear();details.Children.Add(ClinicalPresentation.Safety(result.Deserialize<ClinicalScreenResult>(new JsonSerializerOptions{PropertyNameCaseInsensitive=true})!));}
    async Task Import(){var file=new OpenFileDialog{Filter="Clinical packages|*.json;*.csv;*.zip;*.xlsx"};if(file.ShowDialog()!=true)return;var json=ClinicalImportFormats.Read(file.FileName);await PreviewAndStage(json);}
    async Task PreviewAndStage(string json){var hash=Convert.ToHexString(SHA256.HashData(Encoding.UTF8.GetBytes(json)));var preview=await vm!.Post("clinical/packages/preview",new PackageImport(json,hash,false,""));var text=string.Join("\n",preview.EnumerateObject().Select(x=>x.Name+": "+x.Value));var confirm=new FormWindow("Package preview - no clinical approval\n"+text,[new("rights","I verified lawful use/redistribution for this hospital and each source","bool"),new("reference","Import authorization / licensing reference")],empty){Owner=Window.GetWindow(this)};if(confirm.ShowDialog()!=true)return;await vm.Post("clinical/packages",new PackageImport(json,hash,(bool)confirm.Values["rights"]!,confirm.Values["reference"]!.ToString()!));Rows(await vm.Get("clinical/versions"));status.Text="Draft imported transactionally. It is excluded from clinical screening until reviewed, approved and published.";}
    async Task EditPackage(){var package=await vm!.Get("clinical/versions/"+Value("id")+"/package");var editor=new Window{Title="New draft version - structured package editor",Width=1000,Height=750,Owner=Window.GetWindow(this),WindowStartupLocation=WindowStartupLocation.CenterOwner};var dock=new DockPanel{Margin=new Thickness(16)};editor.Content=dock;var buttons=new WrapPanel();DockPanel.SetDock(buttons,Dock.Bottom);dock.Children.Add(buttons);var preview=new Button{Content="Preview as new draft (change Version first)"};buttons.Children.Add(preview);var text=new TextBox{Text=JsonSerializer.Serialize(package,new JsonSerializerOptions{WriteIndented=true}),AcceptsReturn=true,AcceptsTab=true,VerticalScrollBarVisibility=ScrollBarVisibility.Auto,HorizontalScrollBarVisibility=ScrollBarVisibility.Auto,FontFamily=new FontFamily("Consolas")};dock.Children.Add(text);preview.Click+=(_,_)=>editor.DialogResult=true;if(editor.ShowDialog()==true)await PreviewAndStage(text.Text);}
    async Task Decide(){var id=Value("id");var form=new FormWindow("Clinical content decision",[new("action","Action","choice","Submit|Review|Approve|Publish|Restore publication|Archive"),new("reason","Evidence / clinical review / authorization reference")],empty){Owner=Window.GetWindow(this)};if(form.ShowDialog()!=true)return;await vm!.Post("clinical/versions/"+id+"/decision",new ContentDecision(form.Values["action"]!.ToString()!,form.Values["reason"]!.ToString()!,true));Rows(await vm.Get("clinical/versions"));}
    async Task Map(){var products=await vm!.Get("clinical/products");var medicines=await vm.Get("medicines");var lookups=new Dictionary<string,List<KeyValuePair<string,string>>>{["medicines"]=medicines.EnumerateArray().Select(x=>new KeyValuePair<string,string>(x.GetProperty("id").ToString(),string.Join(" / ",new[]{"genericName","brandName","strength","dosageForm","route"}.Select(k=>x.GetProperty(k).ToString())))).ToList(),["products"]=products.EnumerateArray().Select(x=>new KeyValuePair<string,string>(x.GetProperty("key").ToString(),string.Join(" / ",new[]{"key","brand","drug","strength","form","route"}.Select(k=>x.GetProperty(k).ToString())))).ToList()};var form=new FormWindow("Verify exact clinical-to-inventory mapping",[new("medicine","Existing inventory medicine",Lookup:"medicines"),new("product","Published product",Lookup:"products"),new("reason","Verified ingredients, brand, strength, form, route and package evidence")],lookups){Owner=Window.GetWindow(this)};if(form.ShowDialog()==true){await vm.Post("clinical/mappings",new ClinicalMappingInput(Guid.Parse(form.Values["medicine"]!.ToString()!),form.Values["product"]!.ToString()!,form.Values["reason"]!.ToString()!,true));status.Text="Verified mapping recorded without creating or changing inventory stock.";}}
    async Task Export(){var dialog=new SaveFileDialog{Filter="UTF-8 text report|*.txt",FileName="DDHI-Clinical-Reference.txt"};if(dialog.ShowDialog()!=true)return;await vm!.Post("audit/file-activity",new{action="Export clinical report",outcome="Started",fileName=Path.GetFileName(dialog.FileName),rows=0,page="Drug Reference"});await File.WriteAllTextAsync(dialog.FileName,ClinicalPresentation.Text(details));await vm.Post("audit/file-activity",new{action="Export clinical report",outcome="Succeeded",fileName=Path.GetFileName(dialog.FileName),rows=0,page="Drug Reference"});status.Text="Reference report exported. Review context, sources and coverage limitations are included.";}
    async Task Print(){var dialog=new PrintDialog();if(dialog.ShowDialog()!=true)return;await vm!.Post("audit/file-activity",new{action="Print report",outcome="Started",fileName="",rows=0,page="Drug Reference"});var doc=new FlowDocument{PagePadding=new Thickness(35),FontSize=11};doc.Blocks.Add(new Paragraph(new Run("Digos Doctors Hospital, Inc. - Drug Reference\n"+DateTimeOffset.UtcNow.ToOffset(TimeSpan.FromHours(8)).ToString("yyyy-MM-dd HH:mm:ss")+" Asia/Manila")));doc.Blocks.Add(new Paragraph(new Run(ClinicalPresentation.Text(details))));dialog.PrintDocument(((IDocumentPaginatorSource)doc).DocumentPaginator,"DDHI Clinical Reference");await vm.Post("audit/file-activity",new{action="Print report",outcome="Succeeded",fileName="",rows=0,page="Drug Reference"});}
}
